package agentusageview

import (
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Live updates, step 1 (DEVDESK-45): rebuilding the agent rows while keeping
// the cursor on the same agent, the filter and the sort, and remeasuring only
// when the table holds a different population.

// selectAgent moves the cursor onto the visible row with the given ID ("" is
// the orchestrator).
func selectAgent(t *testing.T, m Model, id string) Model {
	t.Helper()
	for i, r := range m.agentTable.Visible() {
		if r.ID == id {
			m.agentTable.SetCursor(i)
			return m
		}
	}
	t.Fatalf("no visible agent %q in %q", id, visibleIDs(m))
	return m
}

func selectedID(t *testing.T, m Model) string {
	t.Helper()
	r, ok := m.agentTable.Selected()
	if !ok {
		t.Fatal("no agent selected")
	}
	return r.ID
}

func agentColumnWidth(m Model) int { return m.agentTable.Table().Columns()[0].Width }

func TestAgentKeysIdentifyRowsAcrossRebuilds(t *testing.T) {
	tests := []struct {
		name   string
		agents []agentusage.Agent
		want   []string
	}{
		{"orchestrator alone", []agentusage.Agent{orchestrator(1, 0)}, []string{"main"}},
		{
			"tree order",
			[]agentusage.Agent{orchestrator(1, 0), subAgent("a01", "coder", 1, 0), subAgent("a02", "tester", 1, 0)},
			[]string{"main", "sub:a01#0", "sub:a02#0"},
		},
		{
			"two sub-agents sharing one ID stay distinct",
			[]agentusage.Agent{subAgent("dup", "coder", 1, 0), subAgent("dup", "tester", 1, 0)},
			[]string{"sub:dup#0", "sub:dup#1"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := agentKeys(agentRows(agentusage.Usage{Agents: tt.agents}, true))
			if strings.Join(got, "|") != strings.Join(tt.want, "|") {
				t.Errorf("agentKeys = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestACursorStaysOnItsAgentWhenAnotherSortsBeforeIt(t *testing.T) {
	base := agentusage.Usage{Agents: []agentusage.Agent{
		orchestrator(10, 0), subAgent("a01", "coder", 10, 0), subAgent("a02", "tester", 10, 0),
	}}
	m := selectAgent(t, atWideAgents(t, base), "a02")
	if m.agentTable.Cursor() != 2 {
		t.Fatalf("setup: cursor = %d, want 2", m.agentTable.Cursor())
	}

	grown := agentusage.Usage{Agents: append([]agentusage.Agent{subAgent("a00", "planner", 10, 0)}, base.Agents...)}
	m = m.withUsage(grown, false)

	if got := selectedID(t, m); got != "a02" {
		t.Errorf("selected %q after a00 joined, want a02", got)
	}
	if got := m.agentTable.Cursor(); got != 3 {
		t.Errorf("cursor = %d, want 3 (main, a00, a01, a02)", got)
	}
}

func TestACursorFollowsItsAgentWhenTheTotalSortReordersRows(t *testing.T) {
	small := agentusage.Usage{Agents: []agentusage.Agent{
		totalled(orchestrator(0, 0), 1000, 0),
		totalled(subAgent("a01", "coder", 0, 0), 800, 0),
		totalled(subAgent("a02", "tester", 0, 0), 300, 0),
	}}
	m := atWideAgents(t, small)
	m, _ = opened(t, m, ".") // Total, largest first
	if got := visibleIDs(m); got != ",a01,a02" {
		t.Fatalf("setup: sorted order = %q", got)
	}
	m = selectAgent(t, m, "a01")
	if m.agentTable.Cursor() != 1 {
		t.Fatalf("setup: cursor = %d, want 1", m.agentTable.Cursor())
	}

	grown := agentusage.Usage{Agents: []agentusage.Agent{
		small.Agents[0],
		totalled(subAgent("a01", "coder", 0, 0), 2000, 0),
		small.Agents[2],
	}}
	m = m.withUsage(grown, false)

	if got := visibleIDs(m); got != "a01,,a02" {
		t.Fatalf("order after growth = %q, want a01,,a02", got)
	}
	if got := selectedID(t, m); got != "a01" {
		t.Errorf("selected %q, want the coder still", got)
	}
	if got := m.agentTable.Cursor(); got != 0 {
		t.Errorf("cursor = %d, want 0", got)
	}
}

func TestAVanishedAgentClampsTheCursorWithoutPanicking(t *testing.T) {
	m := selectAgent(t, atWideAgents(t, threeSubs()), "a03")

	m = m.withUsage(agentusage.Usage{Agents: threeSubs().Agents[:2]}, true)

	if n := len(m.agentTable.Visible()); n != 2 {
		t.Fatalf("%d rows, want 2", n)
	}
	if _, ok := m.agentTable.Selected(); !ok {
		t.Error("a row must stay selected")
	}
	if c := m.agentTable.Cursor(); c < 0 || c > 1 {
		t.Errorf("cursor = %d out of range", c)
	}
}

func TestTheFilterAndItsBarSurviveAnUpdate(t *testing.T) {
	m := atWideAgents(t, threeSubs())
	m = send(t, m, testutil.Key("/"))
	for _, k := range testutil.Type("test") {
		m = feed(t, m, k)
	}
	m = send(t, m, testutil.Key("enter"))
	if got := visibleIDs(m); got != "a02" {
		t.Fatalf("setup: filter shows %q", got)
	}

	grown := threeSubs()
	grown.Agents[2] = subAgent("a02", "tester", 999, 0)
	m = m.withUsage(grown, false)

	if got := visibleIDs(m); got != "a02" {
		t.Errorf("visible = %q, want only the tester", got)
	}
	if q := m.agentTable.FilterBar().SearchQuery(); q != "test" {
		t.Errorf("query = %q, want test", q)
	}
	if !m.FilterBarVisible() {
		t.Error("the filter bar must stay visible")
	}
}

func TestWithUsageClearsTheLoadingAndErrorStates(t *testing.T) {
	m := atWideAgents(t, threeSubs())
	m.agentsLoading, m.agentsErr = true, true

	m = m.withUsage(threeSubs(), false)

	if m.agentsLoading || m.agentsErr {
		t.Errorf("agentsLoading=%v agentsErr=%v, want both false", m.agentsLoading, m.agentsErr)
	}
}

func TestRemeasureHappensOnlyOnAFullReadOrAChangedPopulation(t *testing.T) {
	long := strings.Repeat("x", 30)
	coderOnly := func(typ string, models ...string) agentusage.Usage {
		c := subAgent("a01", typ, 1, 0)
		if models != nil {
			c.Models = models
		}
		return agentusage.Usage{Agents: []agentusage.Agent{orchestrator(1, 0), c}}
	}
	tests := []struct {
		name      string
		next      agentusage.Usage
		remeasure bool
		widened   bool
	}{
		{"same population, longer type, partial delta", coderOnly(long), false, false},
		{"same population, full read", coderOnly(long), true, true},
		{"a new sub-agent", agentusage.Usage{Agents: []agentusage.Agent{
			orchestrator(1, 0), subAgent("a01", "coder", 1, 0), subAgent("a02", long, 1, 0),
		}}, false, true},
		{"a model added to an existing agent", coderOnly(long, "model-b", "model-c"), false, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := atWideAgents(t, coderOnly("coder"))
			before := agentColumnWidth(m)

			m = m.withUsage(tt.next, tt.remeasure)

			got := agentColumnWidth(m)
			if tt.widened && got < utf8.RuneCountInString(lastStem+long) {
				t.Errorf("Agent column is %d wide, want at least %d", got, len(lastStem+long))
			}
			if !tt.widened && got != before {
				t.Errorf("Agent column went from %d to %d, want unchanged", before, got)
			}
		})
	}
}

func TestANewSubAgentIsRenderedWholeAtOnce(t *testing.T) {
	m := atWideAgents(t, agentusage.Usage{Agents: []agentusage.Agent{
		orchestrator(1, 0), subAgent("a01", "coder", 1, 0),
	}})

	m = m.withUsage(agentusage.Usage{Agents: []agentusage.Agent{
		orchestrator(1, 0), subAgent("a01", "coder", 1, 0), subAgent("a02", "general-purpose", 1, 0),
	}}, false)

	if view := stripANSI(m.View()); !strings.Contains(view, lastStem+"general-purpose") {
		t.Errorf("the new agent's type is cut:\n%s", view)
	}
}
package agentusageview

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Live updates, step 2 (DEVDESK-45): the messages and Cmds of the poll chain.

// copyFixture copies the basic fixture into t.TempDir() and returns its parent
// transcript, so a test can append to it and delete it.
func copyFixture(t *testing.T) string {
	t.Helper()
	src := filepath.Join(filepath.Dir(fixtureParent), "..", "..")
	dst := t.TempDir()
	err := filepath.WalkDir(src, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, p)
		target := filepath.Join(dst, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o700)
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		return os.WriteFile(target, b, 0o600)
	})
	if err != nil {
		t.Fatal(err)
	}
	rel, _ := filepath.Rel(src, fixtureParent)
	return filepath.Join(dst, rel)
}

// runDelta runs readDeltaCmd and returns its answer.
func runDelta(t *testing.T, gen int, c agentusage.Cursor) usageDeltaMsg {
	t.Helper()
	cmd := readDeltaCmd(gen, c)
	if cmd == nil {
		t.Fatal("readDeltaCmd returned nil")
	}
	got, ok := cmd().(usageDeltaMsg)
	if !ok {
		t.Fatalf("readDeltaCmd answered %T, want usageDeltaMsg", cmd())
	}
	return got
}

func TestReadDeltaCmdFirstReadIsFullAndStampedWithGenAndTime(t *testing.T) {
	stamp := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
	old := now
	now = func() time.Time { return stamp }
	t.Cleanup(func() { now = old })

	agg := agentusage.NewAggregate(copyFixture(t))
	got := runDelta(t, 7, agg.Cursor())

	if got.gen != 7 {
		t.Errorf("gen = %d, want 7", got.gen)
	}
	if got.err != nil {
		t.Fatalf("err = %v", got.err)
	}
	if !got.delta.Full() {
		t.Error("the first read of a fresh aggregate must be Full")
	}
	if !got.at.Equal(stamp) {
		t.Errorf("at = %v, want the stubbed now %v", got.at, stamp)
	}
}

func TestReadDeltaCmdAfterApplyIsEmptyUntilRewound(t *testing.T) {
	agg := agentusage.NewAggregate(copyFixture(t))
	first := runDelta(t, 1, agg.Cursor())
	if err := agg.Apply(first.delta); err != nil {
		t.Fatal(err)
	}

	again := runDelta(t, 1, agg.Cursor())
	if again.err != nil || again.delta.Full() || !again.delta.Empty() {
		t.Errorf("unchanged files: err=%v full=%v empty=%v, want an empty incremental delta",
			again.err, again.delta.Full(), again.delta.Empty())
	}
	if rewound := runDelta(t, 1, agg.Cursor().Rewound()); !rewound.delta.Full() {
		t.Error("a Rewound cursor must give a Full read")
	}
}

func TestReadDeltaCmdOnADeletedParentErrsWithoutAPath(t *testing.T) {
	parent := copyFixture(t)
	agg := agentusage.NewAggregate(parent)
	if err := os.Remove(parent); err != nil {
		t.Fatal(err)
	}

	got := runDelta(t, 2, agg.Cursor())

	if !errors.Is(got.err, os.ErrNotExist) {
		t.Fatalf("err = %v, want one that satisfies errors.Is(os.ErrNotExist)", got.err)
	}
	if strings.Contains(got.err.Error(), filepath.Dir(parent)) {
		t.Errorf("the error names a directory: %v", got.err)
	}
}

func TestPollTickCmdYieldsATickOfItsGeneration(t *testing.T) {
	testutil.FastTimers(t, &pollInterval)
	if got, ok := pollTickCmd(3)().(usagePollTickMsg); !ok || got.gen != 3 {
		t.Errorf("pollTickCmd(3) = %+v, want usagePollTickMsg{gen: 3}", got)
	}
}

func TestResumeCmdAnswersAtOnce(t *testing.T) {
	if _, ok := resumeCmd()().(agentsResumeMsg); !ok {
		t.Error("resumeCmd must return agentsResumeMsg")
	}
}

// Production values are pinned, like the footer's three seconds.
func TestPollIntervalAndQuietPeriodProductionValues(t *testing.T) {
	if pollInterval != 2*time.Second {
		t.Errorf("pollInterval = %v, want 2s", pollInterval)
	}
	if quietPeriod != 5*time.Minute {
		t.Errorf("quietPeriod = %v, want 5m", quietPeriod)
	}
}

// Rule 110: the Cmd holds a Cursor copy, so the model's aggregate can be used
// while the read runs. Meaningful under `go test -race`.
func TestReadDeltaCmdDoesNotTouchTheAggregateItsCursorCameFrom(t *testing.T) {
	agg := agentusage.NewAggregate(copyFixture(t))
	cmd := readDeltaCmd(1, agg.Cursor())

	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		cmd()
	}()

	d, err := agentusage.ReadDelta(agg.Cursor())
	if err != nil {
		t.Fatal(err)
	}
	if err := agg.Apply(d); err != nil {
		t.Fatal(err)
	}
	_ = agg.Usage()
	_ = agg.Activity()
	wg.Wait()
}
package agentusageview

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// listSessionsCmd resolves the projects root and lists it, all inside the Cmd:
// the model is not touched (Rule 110) and the answer carries gen back.
func listSessionsCmd(gen int) tea.Cmd {
	return func() tea.Msg {
		root, err := agentusage.ProjectsRoot()
		if err != nil {
			return sessionListLoadedMsg{gen: gen, err: err}
		}
		listing, err := agentusage.ListSessions(root)
		return sessionListLoadedMsg{gen: gen, root: root, listing: listing, err: err}
	}
}

// parseSessionCmd locates and parses a session's transcripts, all inside the
// Cmd (Rule 110). parent is copied in by the caller; the answer carries gen.
func parseSessionCmd(gen int, parent string) tea.Cmd {
	return func() tea.Msg {
		files, err := agentusage.LocateSession(parent)
		if err != nil {
			return sessionUsageLoadedMsg{gen: gen, err: err}
		}
		usage, err := agentusage.ParseSession(files)
		return sessionUsageLoadedMsg{gen: gen, usage: usage, err: err}
	}
}
// Package agentusageview is the `:agent-usage` screen: the Claude Code
// sessions found on this machine.
//
// It reads transcripts' working directory and date only, never their content
// (internal/agentusage owns that guarantee).
package agentusageview

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// sessionRow is one table row. project is computed once, in Update, so a Cell
// never touches the file system or the environment.
type sessionRow struct {
	agentusage.Session
	project string // theme.FoldHome(Project), or "-" when unknown
}

// sessionListLoadedMsg carries one listing. gen drops an answer to a read that
// a newer one has superseded.
type sessionListLoadedMsg struct {
	gen     int
	root    string
	listing agentusage.Listing
	err     error
}

// sessionUsageLoadedMsg carries one parsed session. gen is agentGen at the time
// the parse started: it drops the answer for a session left or re-read since.
type sessionUsageLoadedMsg struct {
	gen   int
	usage agentusage.Usage
	err   error
}

// level is the screen on view: the sessions, or the agents of one session.
type level int

const (
	levelSessions level = iota
	levelAgents
)

// Model is the agent usage view.
type Model struct {
	table   datatable.Model[sessionRow]
	spinner spinner.Model
	footer  sharedcomponents.FooterMessage

	// level says which table is on screen. The sessions table keeps its cursor
	// and filter while the agents level is open.
	level level
	// agentTable lists the agents of open.
	agentTable datatable.Model[agentRow]
	open       agentusage.Session
	// usage is the last parse of open, kept for what the footer says about it.
	usage agentusage.Usage
	// agentGen numbers the parses, as gen numbers the listings.
	agentGen      int
	agentsLoading bool
	// agentsErr says the most recent parse failed (a state, like loadErr).
	agentsErr bool
	// width and height are the last viewport size, for both tables.
	width, height int

	// gen numbers the reads; only the answer to the latest one is kept.
	gen     int
	loading bool
	// loadErr says the most recent read failed. It is a state rather than a
	// timed message so the empty-listing sentence cannot take its place.
	loadErr bool
	// root is the projects directory the last successful read listed.
	root    string
	omitted int
}

// New builds the view with its first read pending.
func New(_ *config.Config) Model {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return Model{
		loading: true,
		spinner: sp,
		table: datatable.New(datatable.Config[sessionRow]{
			Columns: sessionColumns(),
			// The listing arrives newest first, which is the order wanted.
			SortColumn: -1,
		}),
		agentTable: datatable.New(datatable.Config[agentRow]{
			Columns: agentColumns(),
			// Opens as the tree (orchestrator, then sub-agents); `.` sorts by Total.
			SortColumn: -1,
		}),
	}
}

// Init starts the first read and the spinner.
func (m Model) Init() tea.Cmd {
	cmds := []tea.Cmd{listSessionsCmd(m.gen), m.spinner.Tick}
	if m.level == levelAgents {
		cmds = append(cmds, parseSessionCmd(m.agentGen, m.open.Parent))
	}
	return tea.Batch(cmds...)
}
