func sortUsage(testerPartial int) agentusage.Usage {
	return agentusage.Usage{Agents: []agentusage.Agent{
		totalled(orchestrator(0, 0), 1000, 0),
		totalled(subAgent("a01", "coder", 0, 0), 5000, 0),
